function normalizeYearLabel(text) {
    return String(text || "").replace(/\s+/g, "").toLowerCase();
}

function setSelectByYearLabel(selectId, label) {
    var el = getEl(selectId);
    var i;
    var target = normalizeYearLabel(label);
    if (!el || target === "") {
        return false;
    }
    for (i = 0; i < el.options.length; i++) {
        if (normalizeYearLabel(el.options[i].text).indexOf(target) >= 0) {
            el.value = el.options[i].value;
            return true;
        }
    }
    return false;
}

